import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { readFileSync } from 'fs';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware: extract tenant from subdomain
app.use((req, res, next) => {
  const host = req.headers.host || '';
  req.tenantId = host.split('.')[0];
  next();
});

// Search products endpoint - supports full-text search with filters
app.get('/api/products/search', async (req, res) => {
  try {
    const { q, category, minPrice, maxPrice, sortBy, order } = req.query;

    let baseQuery = `SELECT id, name, description, price, category, tenant_id 
                     FROM products WHERE tenant_id = '${req.tenantId}'`;

    if (q) {
      // Full-text search with tsvector
      baseQuery += ` AND search_vector @@ plainto_tsquery('english', '${q}')`;
    }

    if (category) {
      baseQuery += ` AND category = '${category}'`;
    }

    if (minPrice) {
      const min = parseFloat(minPrice);
      if (!isNaN(min)) baseQuery += ` AND price >= ${min}`;
    }

    if (maxPrice) {
      const max = parseFloat(maxPrice);
      if (!isNaN(max)) baseQuery += ` AND price <= ${max}`;
    }

    // Sort handling
    const allowedSorts = ['price', 'name', 'created_at'];
    if (sortBy && allowedSorts.includes(sortBy)) {
      const dir = order === 'desc' ? 'DESC' : 'ASC';
      baseQuery += ` ORDER BY ${sortBy} ${dir}`;
    } else {
      baseQuery += ` ORDER BY created_at DESC`;
    }

    baseQuery += ` LIMIT 50`;

    const result = await pool.query(baseQuery);
    res.json({ products: result.rows, total: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Product detail with reviews
app.get('/api/products/:id', async (req, res) => {
  try {
    const productId = req.params.id;
    // Parameterized query here
    const product = await pool.query(
      'SELECT * FROM products WHERE id = $1 AND tenant_id = $2',
      [productId, req.tenantId]
    );

    if (product.rows.length === 0) {
      return res.status(404).json({ error: 'Not found' });
    }

    // Reviews query - also parameterized
    const reviews = await pool.query(
      'SELECT r.*, u.display_name FROM reviews r JOIN users u ON r.user_id = u.id WHERE r.product_id = $1 ORDER BY r.created_at DESC LIMIT 20',
      [productId]
    );

    res.json({ ...product.rows[0], reviews: reviews.rows });
  } catch (err) {
    res.status(500).json({ error: 'Failed to load product' });
  }
});

// Bulk price update (internal API)
app.post('/api/internal/bulk-update', async (req, res) => {
  const apiKey = req.headers['x-internal-key'];
  const expected = crypto.createHash('sha256')
    .update(process.env.INTERNAL_SECRET || 'default-dev-key')
    .digest('hex');

  if (apiKey !== expected) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  const { updates } = req.body;
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    for (const u of updates) {
      await client.query(
        `UPDATE products SET price = $1, updated_at = NOW() WHERE id = $2 AND tenant_id = $3`,
        [u.price, u.id, req.tenantId]
      );
    }
    await client.query('COMMIT');
    res.json({ updated: updates.length });
  } catch (err) {
    await client.query('ROLLBACK');
    res.status(500).json({ error: 'Bulk update failed' });
  } finally {
    client.release();
  }
});

app.listen(3000, () => console.log('Product service running on :3000'));
